scwin.vs_G_GRP_PROCS_DD = ""; //팝업에 쓰임 
scwin.vs_G_GRP_PROCS_TM = ""; //팝업에 쓰임
scwin.vs_G_BND_MKTACT_TP_CD = ""; //팝업에 쓰임
scwin.vRegYn = 'N';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 함수명   : fn_NewGchKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다. tab1
 ***********************************************/
scwin.fn_NewGchKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vs_G_BND_APPL_ID,
        BND_LIST_PROCS_TP_CD: scwin.vs_G_BND_LIST_PROCS_TP_CD,
        ISU_NM: scwin.vs_G_ISU_NM,
        GRP_PROCS_DD: "",
        GRP_PROCS_TM: "",
        GRP_GB: "01"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


