};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var vo_Dts_List = null;
    var vo_Grd_List = null;
    var vsSqlNm = "";
    var vsInOutNm = "";

    // 개별채권
    if (vsTabSel == "1") {
        vsInOutNm = "BNS_LIST_FEE_AND_ANULFEE_LIST1";
        vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list1";
        vo_Dts_List = dts_List1;
        vo_Grd_List = grd_List1;

        // 변경상장

    } else if (vsTabSel == "2") {
        vsInOutNm = "BNS_LIST_FEE_AND_ANULFEE_LIST21";
        vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list21";
        vo_Dts_List = dts_List21;
        vo_Grd_List = grd_List21;

        // 일괄+선매출채권

    } else if (vsTabSel == "3") {
        vsInOutNm = "BNS_LIST_FEE_AND_ANULFEE_LIST31";
        vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list31";
        vo_Dts_List = dts_List31;
        vo_Grd_List = grd_List31;
    }
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + vsInOutNm;
    url += "&queryId=" + vsSqlNm;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += '&{P}V_COM_NM=' + txb_ISUR_CD.getValue();
    url += '&{P}V_ISU_NM=' + txb_ISU_CD.getValue();
    url += "&{P}V_BND_TP_CD=" + $c.stf.getObjectValue(cmb_BndKnd);
    url += "&{P}V_PAY_YN=" + $c.stf.getObjectValue(cmb_PayYn);
    url += "&{P}V_TERM_TYP=" + $c.stf.getObjectValue(cmb_TermTp);
    url += "&{P}V_STRT_DT=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DT=" + $c.stf.getObjectValue(edt_EDate);
    vo_Dts_List.DataID = encodeURI(url);
    vo_Dts_List.Reset();
    if (vsTabSel == "1") {
        $c.cm.ShowWin(vo_Grd_List);
    } else {
        var arrPnl = [panel_1];
        $c.bns.ShowWinArrPnl(arrPnl, grd_List21);
    }
};



/********************************************** 
 * 설명       : 변경상장/일괄_선매출채권 상세조회
 ***********************************************/
scwin.fn_SearchDetail = function(pGb, row) {
    var vo_Dts_List = null;
    var vo_Grd_List = null;
    var vsSqlNm = "";
    var vsInOutNm = "";
    var vsPGrpProcsDd = "";
    var vsPGrpProcsTm = "";

    // 변경상장
    if (pGb == "2") {
        vsInOutNm = "BNS_LIST_FEE_AND_ANULFEE_LIST22";
        if (dts_List21.getCellData(row, "CO_12") == "201") {
            vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list2201";
            $c.cm.setColumnProp(grd_List22, "STD_CD", "Show", true);
            $c.cm.setColumnProp(grd_List22, "LIST_AMT", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BND_MERGE_OBJ_TP", "Show", false);
            $c.cm.setColumnProp(grd_List22, "ISUR_NM", "Show", false);
            $c.cm.setColumnProp(grd_List22, "OBJ_INST_NM", "Show", false);
            $c.cm.setColumnProp(grd_List22, "INSU_STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BNE_SI_NEW_ISU_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "EXER_AMT", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BW_STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BND_NEW_ISU_CD", "Show", false);
        } else if (dts_List21.getCellData(row, "CO_12") == "202" || dts_List21.getCellData(row, "CO_12") == "203") {
            /**
             * 합병/분할 → 합병/회사분할(202)-N건의 종목관리, 종목분할(203) 
             * 분리된 이후, 변경상장 수수료 발생하지 않음
             */
            vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list2202";
            $c.cm.setColumnProp(grd_List22, "STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "LIST_AMT", "Show", true);
            $c.cm.setColumnProp(grd_List22, "BND_MERGE_OBJ_TP", "Show", true);
            $c.cm.setColumnProp(grd_List22, "ISUR_NM", "Show", true);
            $c.cm.setColumnProp(grd_List22, "OBJ_INST_NM", "Show", true);
            $c.cm.setColumnProp(grd_List22, "INSU_STD_CD", "Show", true);
            $c.cm.setColumnProp(grd_List22, "BND_SI_NEW_ISU_CD", "Show", true);
            $c.cm.setColumnProp(grd_List22, "EXER_AMT", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BW_STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BND_NEW_ISU_CD", "Show", false);
        } else if (dts_List21.getCellData(row, "CO_12") == "205") {
            vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list2205";
            $c.cm.setColumnProp(grd_List22, "STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "LIST_AMT", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BND_MERGE_OBJ_TP", "Show", false);
            $c.cm.setColumnProp(grd_List22, "ISUR_NM", "Show", true);
            $c.cm.setColumnProp(grd_List22, "OBJ_INST_NM", "Show", false);
            $c.cm.setColumnProp(grd_List22, "INSU_STD_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "BND_SI_NEW_ISU_CD", "Show", false);
            $c.cm.setColumnProp(grd_List22, "EXER_AMT", "Show", true);
            $c.cm.setColumnProp(grd_List22, "BW_STD_CD", "Show", true);
            $c.cm.setColumnProp(grd_List22, "BND_NEW_ISU_CD", "Show", true);
        }
        vo_Dts_List = dts_List22;
        vo_Grd_List = grd_List22;
        vsPGrpProcsDd = dts_List21.getCellData(row, "CO_13");
        vsPGrpProcsTm = dts_List21.getCellData(row, "CO_14");

        //일괄+선매출채권

    } else if (pGb == "3") {
        vsInOutNm = "BNS_LIST_FEE_AND_ANULFEE_LIST32";
        if (dts_List31.getCellData(row, "CO_3") == "일괄") {
            vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list321";
        } else {
            vsSqlNm = "lds.stf.bnslist_fee_and_anulfee.select.list322";
        }
        vo_Dts_List = dts_List32;
        vo_Grd_List = grd_List32;
        vsPGrpProcsDd = dts_List31.getCellData(row, "CO_20");
        vsPGrpProcsTm = dts_List31.getCellData(row, "CO_21");
    }
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + vsInOutNm;
    url += "&queryId=" + vsSqlNm;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_GRP_PROCS_DD=" + vsPGrpProcsDd;
    url += "&{P}V_GRP_PROCS_TM=" + vsPGrpProcsTm;
    vo_Dts_List.DataID = encodeURI(url);
    vo_Dts_List.Reset();

    //ShowWin(vo_Grd_List);

};





/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGrid = null;
    var excelSheet = '';

    // 전체조회
    if (vsTabSel == "1") {
        excelSheet = '개별채권';
        voDtsList = dts_List1;
        voGrid = grd_List1;
        // 개별종목조회

    } else if (vsTabSel == "2") {
        excelSheet = '변경상장';
        voDtsList = dts_List21;
        voGrid = grd_List21;
        // 일괄상장종목조회

    } else if (vsTabSel == "3") {
        excelSheet = '일괄+선매출채권';
        voDtsList = dts_List31;
        voGrid = grd_List31;
    }
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_상장수수료및연부과금.xls";
        //voGrid.GridToExcel(excelSheet, "", 8);
        voGrid.GridToOffice(excelSheet, "", 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown2 = function() {
    var excelSheet = '변경상장 그룹지정내역';
    if (dts_List22.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '상장수수료및연부과금';
        //grd_List22.GridToExcel(excelSheet, "", "8");
        $c.data.downloadGridViewOffice(grd_List22, excelSheet, "", 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown3 = function() {
    var excelSheet = '일괄+선매출채권 그룹지정내역';
    if (dts_List32.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '상장수수료및연부과금';
        //grd_List32.GridToExcel(excelSheet, "", "8");
        $c.data.downloadGridViewOffice(grd_List32, excelSheet, "", 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/********************************************** 
 * 함수명   : fn_SetNewBndListFee
 * 설명       : 신규상장 수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
