        BND_APPL_ID: scwin.vs_G_BND_APPL_ID,
        BND_LIST_PROCS_TP_CD: scwin.vs_G_BND_LIST_PROCS_TP_CD,
        MKTACT_TP_CD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

