/**********************************************                                                                               
 * 함수명   : fn_GetParPackSum                                                                                                 
 * 설명       : 팝업에 넘길 데이터를 정의한다.                                                                                 
 ***********************************************/
scwin.fn_GetParPackSum = function(arrPar, param_dts) {
    arrPar[0] = {
        TEST: ''
    };
    $c.stf.CopyDataSetHeader(dts_List1, param_dts);
    var chk;
    for (var idx = 1; idx <= dts_List1.getTotalRow(); idx++) {
        chk = dts_List1.getCellData(idx, "CO_0");
        if (chk == "T" || chk == "1") {
            param_dts.AddRow();
            for (var i = 1; i <= dts_List1.getTotalCol(); i++) {
                param_dts.setCellData(param_dts.getFocusedRowIndex(), dts_List1.getColumnID(i - 1));
            }
        }
    }
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);
    $c.bns.BnsPanelToGroupBox(panel_2);
    $c.bns.BnsPanelToGroupBox(panel_3);
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_Bnd_Kind, '01422'); //채권종류

    tab_Main.setSelectedTabIndex(1);
    if (dts_Bnd_Kind.getCellData(1, "VALUE") == "") {
        dts_Bnd_Kind.setCellData(1, "TEXT", "전체");
        cmb_BndKnd.setSelectedIndex(0);
    }
    $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate); // 신청일 기간	
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 7));
    scwin.fn_Search();
};
