scwin.tab_Main_OnSelChanged = function(nIndex) {
    /********************************************** 
     * 함수명   : tab_Main > OnSelChanged
     * 설명      : 텝 변경
     ***********************************************/
    scwin.fn_Search();
    //개별채권
    if (nIndex == 1) {
        cmb_TermTp.CBData = "0^입금일,1^상장일,2^신청일";
        cmb_TermTp.ResetData();
        btn_All.src = "../img/bns/btn_29.gif";
        btn_All.setDisabled(false);
        cmb_BndKnd.setDisabled(false);

        //변경상장

    } else if (nIndex == 2) {
        cmb_TermTp.CBData = "0^입금일,1^그룹지정일";
        cmb_TermTp.ResetData();
        btn_All.src = "../img/bns/btn_29_d.gif";
        btn_All.setDisabled(true);
        cmb_BndKnd.setDisabled(true);

        // 일괄+선매출채권

    } else if (nIndex == 3) {
        cmb_TermTp.CBData = "0^입금일,1^그룹지정일";
        cmb_TermTp.ResetData();
        btn_All.src = "../img/bns/btn_29_d.gif";
        btn_All.setDisabled(true);
        cmb_BndKnd.setDisabled(true);
    }
};
scwin.grd_List1_OnDblClick = async function(row, colid) {
    /********************************************** 
     * 함수명   : grd_List1 > OnDblClick
     * 설명      : 팝업호출
     ***********************************************/
    //vs_G_LIST_DD         = dts_List1.NameString(row, 'CO_7');             //팝업에 쓰임 
    //vs_G_LIST_DD         = vs_G_LIST_DD.replace(/-/g,"");
    scwin.vs_G_ISU_NM = dts_List1.getCellData(row, 'CO_3'); //팝업에 쓰임 
    scwin.vs_G_BND_APPL_ID = dts_List1.getCellData(row, 'CO_90'); //팝업에 쓰임 
    scwin.vs_G_BND_LIST_PROCS_TP_CD = dts_List1.getCellData(row, 'CO_91'); //팝업에 쓰임 
    scwin.vs_G_BND_MKTACT_TP_CD = dts_List1.getCellData(row, 'CO_24');
    scwin.fn_GetPar = fn_NewGchKey;
    if (row > 0) {
        if (scwin.vs_G_BND_MKTACT_TP_CD == '305') {
            scwin.vRegYn = "N";
            scwin.fn_GetPar = fn_GetAddBndListFee;
            scwin.fn_SetPar = fn_SetAddBndListFee;
            $c.bns.fn_PopAddListFee(grd_List1);
        } else if (scwin.vs_G_BND_MKTACT_TP_CD == '311') {
            scwin.vRegYn = "N";
            scwin.fn_GetPar = fn_AnfeeRefnd;
            scwin.fn_SetPar = fn_SetAnfeeRefndReturn;
            $c.bns.fn_PopOverAnulfee(grd_List1);
        } else {
            scwin.vRegYn = "N";
            scwin.fn_SetPar = fn_SetNewBndListFee;
            $c.bns.fn_SetPopupPos(grd_List1, 'E');
            await $c.frame.CreateDialogFrame("ULDBNS20005", "/bnslistbzappl/ULDBNS20005.gfm", "신규상장수수료 및 연부과금 등록", obj_left, obj_top, 950, 450, "window");
        }
    }
    if (scwin.vRegYn == "Y") {
        scwin.fn_Search();
    }
};
scwin.grd_List21_OnDblClick = function(row, colid) {
    /********************************************** 
     * 함수명   : grd_List21 > OnDblClick
     * 설명      : 팝업호출
     ***********************************************/
    scwin.vs_G_BND_APPL_ID = dts_List21.getCellData(row, 'CO_90'); //팝업에 쓰임 
    scwin.vs_G_BND_MKTACT_TP_CD = ""; //팝업에 쓰임 
