    scwin.vs_G_GRP_PROCS_DD = dts_List21.getCellData(row, 'CO_13'); //팝업에 쓰임 
    scwin.vs_G_GRP_PROCS_TM = dts_List21.getCellData(row, 'CO_14'); //팝업에 쓰임 

    if (row > 0) {
