scwin.btn_All_onclick = async function() {
    /********************************************** 
     * 함수명   : btn_All > onclick
     * 설명      : 일괄합산
     ***********************************************/
    if (!$c.bns.fn_IsChecked(dts_List1, 'CO_0')) {
