};
scwin.grd_List1_OnHeadCheckClick = function(col, colid, bCheck) {
    /********************************************** 
     * 함수명   : grd_List1 > OnHeadCheckClick
     * 설명      : 전체선택
     ***********************************************/
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grd_List1.Redraw = false;
    for (var i = 1; i <= dts_List1.getTotalRow(); i++) {
        dts_List1.setCellData(i, "CO_0", vcd);
    }
    grd_List1.Redraw = true;
};
